insert into products (slug, name, description, long_description, category_id, spice_note, dietary, badge, tagline, rating, review_count, published) values ('mathania-mirch-khakhra', 'Mathania Mirch Khakhra & Farsan', 'Slow hand-pressed whole wheat crisps infused with sweet pungent Mathania chillies.', 'Paper-thin whole wheat khakhras pressed by hand and roasted with Mathania chilli flakes and cumin - light, spicy, and tea-ready.', (select id from categories where slug='tea-time'), 'chatpata', ARRAY['pure-veg','no-palm','jain']::text[], 'Vacuum Sealed', 'Roasted Crisps', 4.7, 540, true) on conflict (slug) do update set name=excluded.name, description=excluded.description, long_description=excluded.long_description, category_id=excluded.category_id, spice_note=excluded.spice_note, dietary=excluded.dietary, badge=excluded.badge, tagline=excluded.tagline, rating=excluded.rating, review_count=excluded.review_count, published=true;
